const { event, slug, url, recipient_email, subject, body } = $json.body;
if (!event || !slug) return [{ json: { ok:false, error:'missing event or slug' } }];
const template = {
  handoff_ready: { subject: `Your ${slug} brand kit is ready`, body: `Preview: ${url}\n\nThanks for the partnership.` },
  phase_ready:   { subject: `Review needed for ${slug}`, body: `Open the portal to review: ${url}` },
  phase_approved:{ subject: `${slug}: phase approved`, body: `Next step is underway.` }
};
const t = template[event] ?? { subject, body };
return [{ json: { slug, recipient_email, subject: t.subject, body: t.body } }];
